{
  "name": "@hung319/opencode-hive",
  "version": "2.2.2",
  "type": "module",
  "description": "OpenCode plugin for Agent Hive - 6 agents, 17 tools, 14 skills",
  "license": "MIT WITH Commons-Clause",
  "author": "hung319",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/hung319/agent-hive.git",
    "directory": "packages/opencode-hive"
  },
  "homepage": "https://github.com/hung319/agent-hive#readme",
  "bugs": {
    "url": "https://github.com/hung319/agent-hive/issues"
  },
  "keywords": [
    "opencode",
    "ai",
    "hive",
    "vibe-coding",
    "workflow",
    "planning",
    "agent"
  ],
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "scripts": {
    "clean": "rm -rf dist",
    "generate-skills": "bun run scripts/generate-skills.ts",
    "build": "npm run clean && npm run generate-skills && bun build src/index.ts --outdir dist --target node --format esm --packages=bundle --external @opencode/plugin --external @ast-grep/napi --external simple-git --external @colbymchenry/codegraph && tsc --emitDeclarationOnly",
    "dev": "bun run generate-skills && bun build src/index.ts --outdir dist --target node --format esm --watch",
    "test": "bun test"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.1.0"
  },
  "dependencies": {
    "@ast-grep/napi": "^0.51.0",
    "@colbymchenry/codegraph": "1.6.2",
    "simple-git": "^4.0.2",
    "zod": "^4.6.7"
  },
  "peerDependenciesMeta": {
    "grep-mcp": {
      "optional": true
    },
    "@upstash/context7-mcp": {
      "optional": true
    },
    "exa-mcp-server": {
      "optional": true
    },
    "auto-cr-cmd": {
      "optional": true
    },
    "@openserp/mcp": {
      "optional": true
    }
  },
  "devDependencies": {
    "hive-core": "workspace:*",
    "@types/bun": "^1.4.4",
    "@types/node": "^26.6.5",
    "typescript": "^7.0.2",
    "@opencode/plugin": "^2.1.4",
    "@opencode/client": "^2.1.4"
  },
  "files": [
    "dist/",
    "skills/",
    "README.md"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./package.json": "./package.json"
  }
}
